import { Component, computed } from '@angular/core';
import { PageHeaderComponent } from '../../shared/components/page-header/page-header.component';
import { ASSET_CREDITS, ASSETS_GENERATED_AT } from '../../core/config/asset-manifest';

interface CreditGroup {
  source: string;
  items: { subject: string; file: string; license: string }[];
}

/**
 * Attribution page for every image shipped with the app. The manifest is
 * generated by `npm run assets:fetch`, so this page cannot drift from the files.
 */
@Component({
  selector: 'app-credits',
  standalone: true,
  imports: [PageHeaderComponent],
  template: `
    <div class="page credits-page">
      <app-page-header
        eyebrow="Attribution"
        title="Credits & licensing"
        subtitle="Every mark, circuit map and photograph in the app, with its source. This is an unofficial, non-commercial student project."
      />

      <section class="notice">
        <h2>Trademark notice</h2>
        <p>
          Formula 1, F1, the F1 logo, team names, team marks and circuit names are trademarks of Formula One
          Licensing B.V., the FIA and the respective teams. They appear here for identification and commentary only.
          Photography and circuit diagrams remain the property of their listed authors and are used under the
          licences shown below.
        </p>
      </section>

      <div class="meta">
        <span>{{ credits().length }} assets</span>
        <span>Manifest generated {{ generatedAt }}</span>
      </div>

      @for (group of groups(); track group.source) {
        <section class="group">
          <h2>{{ group.source }}</h2>
          <div class="panel">
            <table class="data-table">
              <thead>
                <tr>
                  <th>Asset</th>
                  <th>File</th>
                  <th>Licence / status</th>
                </tr>
              </thead>
              <tbody>
                @for (item of group.items; track item.file) {
                  <tr>
                    <td>{{ item.subject }}</td>
                    <td class="file">{{ item.file }}</td>
                    <td class="licence">{{ item.license }}</td>
                  </tr>
                }
              </tbody>
            </table>
          </div>
        </section>
      }
    </div>
  `,
  styles: [
    `
      .credits-page {
        max-width: 1040px;
      }

      .notice {
        padding: 1.1rem 1.25rem;
        margin-bottom: 1.5rem;
        background: var(--surface-2);
        border: 1px solid var(--border);
        border-left: 3px solid var(--accent);
        border-radius: var(--r-xs);
      }

      .notice h2 {
        font-size: 0.78rem;
        letter-spacing: 0.1em;
        text-transform: uppercase;
        color: var(--text-3);
        margin-bottom: 0.4rem;
      }

      .notice p {
        font-family: var(--font-serif);
        font-size: 0.98rem;
        line-height: 1.65;
        max-width: 78ch;
      }

      .meta {
        display: flex;
        justify-content: space-between;
        gap: 1rem;
        padding-bottom: 1.25rem;
        font-size: 0.75rem;
        letter-spacing: 0.06em;
        text-transform: uppercase;
        color: var(--text-3);
      }

      .group {
        margin-bottom: 2rem;
      }

      .group h2 {
        font-size: 1.05rem;
        margin-bottom: 0.6rem;
      }

      .panel {
        overflow-x: auto;
      }

      .file {
        font-family: ui-monospace, 'SFMono-Regular', Consolas, monospace;
        font-size: 0.78rem;
        color: var(--text-3);
      }

      .licence {
        color: var(--text-2);
        white-space: nowrap;
      }
    `,
  ],
})
export class CreditsComponent {
  readonly generatedAt = new Date(ASSETS_GENERATED_AT).toLocaleDateString('en-GB', {
    day: 'numeric',
    month: 'short',
    year: 'numeric',
  });

  readonly credits = computed(() => ASSET_CREDITS);

  readonly groups = computed<CreditGroup[]>(() => {
    const bySource = new Map<string, CreditGroup['items']>();
    for (const item of this.credits()) {
      const list = bySource.get(item.source) ?? [];
      list.push({ subject: item.subject, file: item.file, license: item.license });
      bySource.set(item.source, list);
    }
    return [...bySource.entries()]
      .map(([source, items]) => ({
        source,
        items: items.sort((a, b) => a.subject.localeCompare(b.subject)),
      }))
      .sort((a, b) => a.source.localeCompare(b.source));
  });
}
